import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, uv, vec2, add, sub, mul, float, color } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, BoxGeometry, PlaneGeometry, Vector3 } = ctx.THREE;

  // Helper to build gradient material
  function createGradientMaterial() {
    const mat = new MeshStandardNodeMaterial();
    mat.metalness = 0.45;
    mat.roughness = 0.5;
    mat.clearcoat = 0.2;
    mat.clearcoatRoughness = 0.1;
    // diagonal gradient 135deg: use uv.x + uv.y
    const grad = mix(
      color('#101017'),
      color('#1a1a22'),
      mul(add(uv().x, uv().y), float(0.5))
    );
    mat.colorNode = grad;
    mat.transparent = true;
    mat.opacity = 0; // start invisible for animation
    return mat;
  }

  // Helper to build emissive tick material
  function createTickMaterial() {
    const mat = new MeshBasicNodeMaterial();
    mat.colorNode = color('#ff2a38');
    mat.emissiveNode = color('#ff2a38');
    mat.emissiveIntensity = 1.3;
    mat.transparent = true;
    mat.opacity = 0;
    return mat;
  }

  // Helper to position text objects
  function addText(parent, text, opts, offsetY) {
    const txt = ctx.fontAtlas.createText(text, {
      fontSize: opts.fontSize,
      color: opts.color,
      align: 'left',
      maxWidthPx: 0,
      letterSpacingPx: opts.letterSpacingPx,
    });
    txt.position.set(-parent.userData.width / 2 + 0.5 + txt.userData.width / 2, offsetY, 0.031);
    parent.add(txt);
    return txt;
  }

  // Build grid container
  const root = new Group();
  root.userData.handlers = {};
  root.userData.cleanup = () => {};

  const timelines = [];

  // Cell definitions
  const cells = [
    {
      // Dominant cell (left column spanning both rows)
      width: 3.25,
      height: 3.5,
      isDominant: true,
      value: '0.002 mm',
      label: 'Case tolerance, CNC pass',
      valueOpts: { fontSize: 124, color: '#e8ecf2', letterSpacingPx: -0.01 },
      labelOpts: { fontSize: 18, color: '#16161d', letterSpacingPx: 0.08 },
    },
    {
      // Top right secondary
      width: 2.0,
      height: 1.625,
      isDominant: false,
      value: '38 h',
      label: 'Power reserve, NA-01',
      valueOpts: { fontSize: 68, color: '#e8ecf2', letterSpacingPx: -0.005 },
      labelOpts: { fontSize: 18, color: '#16161d', letterSpacingPx: 0.08 },
    },
    {
      // Bottom right secondary
      width: 2.0,
      height: 1.625,
      isDominant: false,
      value: '214',
      label: 'Components per calibre',
      valueOpts: { fontSize: 68, color: '#e8ecf2', letterSpacingPx: -0.005 },
      labelOpts: { fontSize: 18, color: '#16161d', letterSpacingPx: 0.08 },
    },
  ];

  // Positioning offsets for grid (centered)
  const gutter = 0.25;
  const startX = - (3.25 + gutter + 2.0) / 2 + 3.25 / 2;
  const startY = (3.5) / 2 - 1.625 / 2;

  cells.forEach((cell, idx) => {
    const group = new Group();
    group.userData.width = cell.width;
    group.userData.height = cell.height;
    // geometry
    const geom = new BoxGeometry(cell.width, cell.height, 0.06);
    const mat = createGradientMaterial();
    const mesh = new Mesh(geom, mat);
    mesh.position.set(0, 0, 0.03);
    group.add(mesh);

    // tick bar
    const tickGeom = new PlaneGeometry(0.4, 0.05);
    const tickMat = createTickMaterial();
    const tick = new Mesh(tickGeom, tickMat);
    const pad = 0.5;
    tick.position.set(
      -cell.width / 2 + pad + 0.2,
      cell.height / 2 - pad - 0.025,
      0.04
    );
    group.add(tick);

    // value text
    const valueTxt = ctx.fontAtlas.createText(cell.value, {
      fontSize: cell.valueOpts.fontSize,
      color: cell.valueOpts.color,
      align: 'left',
      letterSpacingPx: cell.valueOpts.letterSpacingPx,
    });
    valueTxt.position.set(
      -cell.width / 2 + pad,
      cell.height / 2 - pad - cell.valueOpts.fontSize * 0.001,
      0.031
    );
    group.add(valueTxt);

    // label text
    const labelTxt = ctx.fontAtlas.createText(cell.label, {
      fontSize: cell.labelOpts.fontSize,
      color: cell.labelOpts.color,
      align: 'left',
      letterSpacingPx: cell.labelOpts.letterSpacingPx,
    });
    labelTxt.position.set(
      -cell.width / 2 + pad,
      valueTxt.position.y - cell.valueOpts.fontSize * 0.001 - 0.1,
      0.031
    );
    group.add(labelTxt);

    // compute grid position
    let x, y;
    if (cell.isDominant) {
      x = startX - 3.25 / 2 + cell.width / 2;
      y = 0;
    } else {
      x = startX + 3.25 / 2 + gutter + cell.width / 2;
      y = idx === 1 ? startY : -startY;
    }
    group.position.set(x, y, 0);
    root.add(group);

    // entrance animation (fade-up)
    const tl = gsap.timeline({ defaults: { ease: 'power2.out' } });
    tl.fromTo(
      mesh.material,
      { opacity: 0, y: 0.2 },
      { opacity: 1, y: 0, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
      0
    );
    tl.fromTo(
      tick.material,
      { opacity: 0, y: 0.2 },
      { opacity: 1, y: 0, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
      0
    );
    tl.fromTo(
      valueTxt,
      { opacity: 0, y: 0.2 },
      { opacity: 1, y: 0, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
      0
    );
    tl.fromTo(
      labelTxt,
      { opacity: 0, y: 0.2 },
      { opacity: 1, y: 0, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
      0
    );
    timelines.push(tl);

    // hover handlers
    const hoverIn = gsap.timeline();
    hoverIn.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'cubic-bezier(0.175,0.885,0.32,1.275)' });
    const hoverOut = gsap.timeline();
    hoverOut.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'cubic-bezier(0.165,0.84,0.44,1)', onComplete: () => {} });
    group.userData.handlers.hoverIn = () => hoverIn.play();
    group.userData.handlers.hoverOut = () => hoverOut.play();

    // store cleanup for this cell
    const cellCleanup = () => {
      geom.dispose();
      mat.dispose();
      tickGeom.dispose();
      tickMat.dispose();
      // dispose text objects if they have dispose method
      if (valueTxt.geometry && valueTxt.geometry.dispose) valueTxt.geometry.dispose();
      if (labelTxt.geometry && labelTxt.geometry.dispose) labelTxt.geometry.dispose();
    };
    if (!root.userData.cleanup) root.userData.cleanup = () => {};
    const prevCleanup = root.userData.cleanup;
    root.userData.cleanup = () => {
      prevCleanup();
      cellCleanup();
    };
  });

  // Header caption above grid
  const header = ctx.fontAtlas.createText('ATELIER METRICS / Q2 2026', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 0.12,
  });
  header.position.set(-2.75, 1.75, 0);
  root.add(header);
  const headerMat = new MeshBasicNodeMaterial();
  headerMat.transparent = true;
  headerMat.opacity = 0;
  header.material = headerMat;
  const headerTl = gsap.timeline();
  headerTl.fromTo(
    headerMat,
    { opacity: 0, y: 0.2 },
    { opacity: 1, y: 0, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }
  );
  timelines.push(headerTl);

  // master timeline with stagger
  const master = gsap.timeline();
  master.add(timelines, 0);
  master.staggerTo(
    timelines.map(t => t.targets()[0]),
    { opacity: 1 },
    0.08,
    0
  );

  // expose cleanup
  root.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    master.kill();
    // dispose materials and geometries stored in userData
    root.traverse(obj => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) obj.material.forEach(m => m.dispose());
        else obj.material.dispose();
      }
    });
  };

  return root;
}
